def _maxpool_kernel(x_ref, out_ref):
    oh, ow = out_ref.shape[-2:]

    acc = x_ref[0, :, 0:2 * oh:2, 0:2 * ow:2]
    for dy in range(3):
        for dx in range(3):
            if dy == 0 and dx == 0:
                continue
            value = x_ref[
                0,
                :,
                dy:dy + 2 * oh:2,
                dx:dx + 2 * ow:2,
            ]
            acc = jnp.maximum(acc, value)

    out_ref[0] = acc


@jax.jit
def workload(x):
    n, c, h, w = x.shape
    oh = (h + 1) // 2
    ow = (w + 1) // 2

    channel_block = 1
    for candidate in (8, 4, 2):
        if c % candidate == 0:
            channel_block = candidate
            break

    padded_w = ((w + 2 + 127) // 128) * 128
    padded = jnp.pad(
        x,
        ((0, 0), (0, 0), (1, 1), (1, padded_w - w - 1)),
        constant_values=jnp.asarray(float("-inf"), dtype=x.dtype),
    )

    return pl.pallas_call(
        _maxpool_kernel,
        out_shape=jax.ShapeDtypeStruct((n, c, oh, ow), x.dtype),
        grid=(n, c // channel_block),
        in_specs=[
            pl.BlockSpec(
                (1, channel_block, h + 2, padded_w),
                lambda i, j: (i, j, 0, 0),
            )
        ],
        out_specs=pl.BlockSpec(
            (1, channel_block, oh, ow),
            lambda i, j: (i, j, 0, 0),
        ),
        compiler_params=pltpu.CompilerParams(
            dimension_semantics=("parallel", "parallel")
        ),
    )(padded)

