def _relu_twosided_kernel(x_ref, lam_ref, out_ref):
    value = x_ref[0, 0, :, :].astype(jnp.float32)
    lam_f32 = lam_ref[...].astype(jnp.float32)
    channel_lam = lam_f32[0, 0, 0, 0]
    threshold = channel_lam / 100.0
    result = jnp.maximum(jnp.abs(value) - threshold, 0.0) * jnp.sign(value)
    out_ref[0, 0, :, :] = result.astype(out_ref.dtype)


def workload(x, lam):
    batch, channels, height, width = x.shape
    plane_block = (1, 1, height, width)

    def plane_map(batch_index, channel_index):
        return (batch_index, channel_index, 0, 0)

    def lam_map(batch_index, channel_index):
        del batch_index
        return (0, channel_index, 0, 0)

    return pl.pallas_call(
        _relu_twosided_kernel,
        out_shape=jax.ShapeDtypeStruct(x.shape, x.dtype),
        grid=(batch, channels),
        in_specs=[
            pl.BlockSpec(plane_block, plane_map),
            pl.BlockSpec((1, 1, 1, 1), lam_map),
        ],
        out_specs=pl.BlockSpec(plane_block, plane_map),
    )(x, lam)

